import zipfile, xml.etree.ElementTree as ET, os, glob

def read_docx(path):
    print('=== ' + path + ' ===')
    with zipfile.ZipFile(path) as z:
        xml_content = z.read('word/document.xml')
    tree = ET.fromstring(xml_content)
    ns = {'w': 'http://schemas.openxmlformats.org/wordprocessingml/2006/main'}
    for body_child in tree.find('w:body', ns):
        tag = body_child.tag.split('}')[-1]
        if tag == 'p':
            texts = [t.text for t in body_child.findall('.//w:t', ns) if t.text]
            if texts:
                print(''.join(texts))
        elif tag == 'tbl':
            print('[TABLE]')
            for row in body_child.findall('.//w:tr', ns):
                cells = []
                for cell in row.findall('.//w:tc', ns):
                    ctext = ' '.join([''.join([t.text for t in p.findall('.//w:t', ns) if t.text]) for p in cell.findall('.//w:p', ns)]).strip()
                    cells.append(ctext)
                print(' | '.join(cells))
            print('[/TABLE]')

base = '/filesystem/final_batch4__electrical_task8_electrical_specs__blind'
for f in sorted(glob.glob(base + '/00_contract/*.docx') + glob.glob(base + '/01_owner/*.docx') + glob.glob(base + '/01_owner/_superseded/*.docx')):
    read_docx(f)
"

